"""Two documents from one registry.

`docs/VENDOR.md` is the long form: every adoption, every decline, the reasoning.
A person reads it once when they need to know why something is the way it is.

`docs/VENDOR-CARD.md` is what an agent loads — one line per upstream, under a
token budget, enough to route on. An agent that needs the detail can read the
long form or call `pf vendor why <path>`; making it carry all of it in every
session would cost more than the answer is worth.

Both are generated. The alternative — a hand-written page next to a machine-read
registry — is the exact failure this whole layer exists to prevent: two accounts
of the same fact, one of which is quietly wrong.
"""

from __future__ import annotations

from pathlib import Path

from pf.vendor.model import Upstream, load_registry

#: Raised from 700 when the catalogue layer landed: four upstreams joined at once
#: (openmetadata, openmetadata-standards, forge, shadcn-admin) and the card went
#: to ~717. The budget is a guard against this file quietly becoming expensive to
#: load, not a fixed constant — but it is only worth having if raising it is a
#: deliberate act with a reason attached, so raise it the same way: recalibrate
#: when the roster genuinely grows, and trim summaries when it is prose that grew.
#: One row costs roughly 15 tokens, so this leaves room for about five more.
VENDOR_CARD_BUDGET = 800

ROLE_ORDER = {"spec": 0, "skills": 1, "shape": 2, "reference": 3}


def _sorted(ups: list[Upstream]) -> list[Upstream]:
    return sorted(ups, key=lambda u: (ROLE_ORDER.get(u.role, 9), u.id))


def render_card(root: str | Path, out: str | Path | None = None) -> Path:
    """The always-loadable index: what each upstream is for, in one line."""
    from pf.vendor.model import drift

    root = Path(root)
    ups = _sorted(load_registry())
    state = {d.upstream_id: d for d in drift(root)}

    lines = [
        "# Vendored upstreams — index",
        "",
        "Generated by `pf vendor card`. Detail: `docs/VENDOR.md` · "
        "`pf vendor why <file>` · `pf vendor list -v`.",
        "",
        "| upstream | for | coupling | state |",
        "|---|---|---|---|",
    ]
    for u in ups:
        d = state.get(u.id)
        kinds = sorted({a.kind for a in u.adopted})
        st = ("drift" if d and d.needs_review
              else "unreviewed" if d and not d.locked
              else "ok")
        if u.needs_licence_review:
            st += " · licence?"
        lines.append(f"| `{u.id}` | {_purpose(u)} | {', '.join(kinds)} | {st} |")

    contracts = [(u.id, a.upstream) for u in ups for a in u.adopted
                 if a.kind in ("schema", "parity")]
    lines += [
        "",
        "**Contracts that can fail a build** — our output is validated against "
        "the vendored file, not against memory:",
        "",
    ]
    lines += [f"- `{i}` → `{p}`" for i, p in contracts]
    lines += [
        "",
        "Rules: never edit `vendor/**` · a submodule bump needs a human "
        "(`pf vendor approve`) · `pf vendor drift` names the files to re-read.",
        "",
    ]
    path = Path(out) if out else root / "docs" / "VENDOR-CARD.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines))
    return path


def _purpose(u: Upstream) -> str:
    """The hand-written one-liner, falling back to the first sentence of `why`.

    Truncating `why` produced lines that stopped mid-clause — technically under
    budget and useless to route on. A summary someone wrote on purpose is worth
    the extra field.
    """
    if u.summary:
        return u.summary
    text = " ".join(u.why.split())
    first = text.split(". ")[0].rstrip(".")
    return first if len(first) <= 90 else first[:87] + "..."


def render_doc(root: str | Path, out: str | Path | None = None) -> Path:
    """The long form: every adoption and every decline, with the reasoning."""
    root = Path(root)
    ups = _sorted(load_registry())
    n_adopt = sum(len(u.adopted) for u in ups)
    n_decline = sum(len(u.declined) for u in ups)

    lines = [
        "# Vendored upstreams",
        "",
        "<!-- GENERATED by `pf vendor doc` from platform/src/pf/vendor/registry.yaml.",
        "     Edit the registry, not this file. -->",
        "",
        f"{len(ups)} upstreams, pinned as submodules under `vendor/`. "
        f"{n_adopt} adoptions, {n_decline} explicit declines.",
        "",
        "Every borrowing below is a path pair — one file upstream, one or more of",
        "ours — so the claim is verifiable rather than remembered. `pf vendor verify`",
        "fails if an upstream path stops existing; `pf vendor drift` names the files",
        "of ours that an upstream change implicates.",
        "",
        "## How the pins stay current",
        "",
        "```bash",
        "pf vendor list          # every upstream, licence, pinned commit, state",
        "pf vendor sync          # fetch each tracking branch, then report",
        "pf vendor drift         # what moved since a human last looked",
        "pf vendor approve <id>  # record the current checkout as reviewed",
        "pf vendor verify        # declared paths still exist; contracts still hold",
        "pf vendor why <file>    # where did this file of ours come from",
        "```",
        "",
        "`.gitmodules` carries `branch =` for each, so `git submodule update --remote`",
        "follows the upstream default branch. The eight added most recently are",
        "`shallow = true` — we want the tip, never the history.",
        "",
        "**`vendor.lock.json` is not the gitlink.** The submodule pointer records which",
        "commit is checked out; the lock records which commit a person *reviewed*, plus",
        "a git OID per adopted path. Those diverge the moment someone runs `--remote`",
        "without reading anything, and the gap between them is the only thing that makes",
        "drift observable. An upstream that moved forty commits without touching",
        "anything we adopted is a free fast-forward; one that touched a schema stops.",
        "",
        "Automation runs weekly (`.github/workflows/vendor-sync.yml`) and opens a PR.",
        "It never approves — approval means a human read the diff, and a workflow",
        "cannot mean that.",
        "",
        "## Coupling kinds",
        "",
        "| kind | meaning | an upstream change… |",
        "|---|---|---|",
        "| `schema` | our output is validated against the vendored file | can fail a build |",
        "| `data` | we read the file at runtime | changes behaviour |",
        "| `parity` | we check our structure against upstream's required fields | means we may be missing a concept |",
        "| `port` | we reimplemented it for our runtime | means re-read one of our files |",
        "| `shape` | we adopted a structure or an idea | is informational |",
        "",
    ]

    flagged = [u for u in ups if u.needs_licence_review]
    if flagged:
        lines += ["## Licence review outstanding", ""]
        for u in flagged:
            lines += [f"### `{u.id}` — {u.licence}", "",
                      " ".join(u.licence_review.split()), ""]

    lines += ["## Licences", "", "| upstream | licence |", "|---|---|"]
    lines += [f"| `{u.id}` | {u.licence}"
              + (" ⚠️" if u.needs_licence_review else "") + " |" for u in ups]
    lines.append("")

    for u in ups:
        lines += [
            "---", "",
            f"## {u.name}", "",
            f"`{u.id}` · [{u.url}]({u.url}) · `{u.path}` @ `{u.branch}` · "
            f"{u.role} · {u.licence}",
            "",
            " ".join(u.why.split()),
            "",
            f"### Adopted ({len(u.adopted)})", "",
        ]
        for a in u.adopted:
            ours = ", ".join(f"`{o}`" for o in a.ours)
            lines.append(f"- **`{a.upstream}`** → {ours}  ·  _{a.kind}_")
            if a.note:
                lines.append(f"  {' '.join(a.note.split())}")
        lines += ["", f"### Deliberately not taken ({len(u.declined)})", ""]
        for x in u.declined:
            lines.append(f"- **{x.what}** — {' '.join(x.why.split())}")
        lines.append("")

    path = Path(out) if out else root / "docs" / "VENDOR.md"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines))
    return path
